  if (response && Array.isArray(response.results)) {
    return response.results;
  }
  return [];
};

const getMemoryText = (memory) => {
  if (!memory) return "";
  return (
    memory.text ||
    memory.memory ||
    memory.content ||
    memory.message ||
    ""
  );
};

