    results: highPriorityMemories,
  };

  await writeJson(
    "/home/user/mem0-metadata-task/high_priority_search.json",
    highPriorityArtifact
  );

  const financeMemory = financeMemories.find((memory) =>
    getMemoryText(memory).toLowerCase().includes("tax")
